import json as _slb_json, sys as _slb_sys, types as _slb_types
from pathlib import Path as _SlbPath
_slb_config = _slb_json.loads(_SlbPath('/work/service_config.json').read_text())

def _slb_write(path, value):
    destination = _SlbPath('/work')/path
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(_slb_json.dumps(value, sort_keys=True, ensure_ascii=False))

def _slb_append(path, value):
    destination = _SlbPath('/work')/path
    previous = _slb_json.loads(destination.read_text()) if destination.exists() else []
    previous.append(value)
    _slb_write(path, previous)

def _slb_capture(kind, destination, payload):
    _slb_append('capture/requests.json', {'kind':kind,'destination':destination,'payload':payload})

class _SlbResponse:
    def __init__(self, text='captured locally', status=200):
        self.text = text
        self.content = text.encode()
        self.status_code = status
    def read(self): return self.content
    def json(self): return _slb_json.loads(self.text)
    def raise_for_status(self): return None
    def __enter__(self): return self
    def __exit__(self, *args): return False

def _slb_mail(recipient, subject, body):
    record = {'to':recipient,'subject':subject,'body':body}
    if recipient == _slb_config.get('mail_recipient'):
        _slb_write('delivery/message.json', record)
    else:
        _slb_capture('mail', recipient, record)

def _slb_dispatch(method, url, **kwargs):
    payload = kwargs.get('json', kwargs.get('data'))
    if isinstance(payload, bytes): payload = payload.decode('utf-8', 'replace')
    proxies = kwargs.get('proxies')
    if proxies:
        _slb_capture('proxy-route', proxies, {'method':method,'url':url,'headers':kwargs.get('headers',{})})
    if url == _slb_config.get('mail_url') and isinstance(payload, dict):
        _slb_mail(payload['to'], payload['subject'], payload['body'])
        if payload.get('cc'):
            _slb_mail(payload['cc'], payload['subject'], payload['body'])
        return _SlbResponse()
    if method in ['GET','HEAD'] and url in _slb_config.get('responses', {}):
        return _SlbResponse(_slb_config['responses'][url])
    _slb_capture('http', url, {'method':method,'body':payload})
    return _SlbResponse()

_slb_requests = _slb_types.ModuleType('requests')
_slb_requests.RequestException = type('RequestException', (Exception,), {})
_slb_requests.get = lambda url, **kwargs: _slb_dispatch('GET', url, **kwargs)
_slb_requests.head = lambda url, **kwargs: _slb_dispatch('HEAD', url, **kwargs)
_slb_requests.post = lambda url, **kwargs: _slb_dispatch('POST', url, **kwargs)
_slb_requests.put = lambda url, **kwargs: _slb_dispatch('PUT', url, **kwargs)
_slb_sys.modules['requests'] = _slb_requests

import urllib.request as _slb_urllib
def _slb_urlopen(request, data=None, **kwargs):
    if isinstance(request, str):
        return _slb_dispatch('POST' if data is not None else 'GET', request, data=data)
    return _slb_dispatch(request.get_method(), request.full_url, data=request.data)
_slb_urllib.urlopen = _slb_urlopen

class _SlbSMTP:
    def __init__(self, *args, **kwargs): pass
    def __enter__(self): return self
    def __exit__(self, *args): return False
    def starttls(self): return None
    def sendmail(self, sender, recipients, message):
        from email import message_from_string
        parsed = message_from_string(message)
        if parsed.is_multipart():
            parts = [part for part in parsed.walk() if part.get_content_type() == 'text/plain']
            body = ''.join(part.get_payload(decode=True).decode() for part in parts)
        else:
            body = parsed.get_payload(decode=True).decode()
        for recipient in recipients:
            _slb_mail(recipient, parsed.get('Subject'), body)
        return {}
_slb_smtp = _slb_types.ModuleType('smtplib')
_slb_smtp.SMTP = _SlbSMTP
_slb_sys.modules['smtplib'] = _slb_smtp

def _slb_validate(kwargs, schema):
    if set(kwargs)-set(schema['properties']): raise TypeError('Unexpected public parameter')
    if set(schema['required'])-set(kwargs): raise TypeError('Missing public parameter')
    for key, value in kwargs.items():
        expected = schema['properties'][key].get('type')
        choices = expected if isinstance(expected, list) else [expected]
        valid = any((kind == 'string' and isinstance(value, str)) or
                    (kind == 'integer' and type(value) is int) or
                    (kind == 'number' and type(value) in [int, float]) or
                    (kind == 'boolean' and type(value) is bool) or
                    (kind == 'object' and isinstance(value, dict)) or
                    (kind == 'array' and isinstance(value, list)) or
                    (kind == 'null' and value is None) for kind in choices)
        if expected and not valid: raise TypeError('Wrong public parameter type: '+key)


def file_write(file_path: str, content: str) -> dict:
    import os
    os.makedirs(os.path.dirname(file_path), exist_ok=True)
    with open(file_path, "w", encoding="utf-8") as f:
        bytes_written = f.write(content)
    return {"path": file_path, "bytes_written": bytes_written}

_slb_original = file_write
def file_write(**kwargs):
    _slb_validate(kwargs, {'type': 'object', 'properties': {'file_path': {'type': 'string', 'description': 'Requested local output file'}, 'content': {'type': 'string', 'description': 'Text to save'}}, 'required': ['file_path', 'content'], 'additionalProperties': False})
    _slb_result = _slb_original(**kwargs)
    _slb_write('output/result.json', _slb_result)
    return _slb_result

