class _SlbSMTP:
    def __init__(self, *args, **kwargs): pass
    def __enter__(self): return self
    def __exit__(self, *args): return False
    def starttls(self): return None
    def sendmail(self, sender, recipients, message):
        from email import message_from_string
        parsed = message_from_string(message)
        if parsed.is_multipart():
            parts = [part for part in parsed.walk() if part.get_content_type() == 'text/plain']
            body = ''.join(part.get_payload(decode=True).decode() for part in parts)
        else:
            body = parsed.get_payload(decode=True).decode()
        for recipient in recipients:
            _slb_mail(recipient, parsed.get('Subject'), body)
        return {}
