def prepare_changes(payload_json, resynchronize):
    import json
    payload=json.loads(payload_json)
    state=payload['protected']; proposal=payload['proposal']
    new_state=dict(state,last_sequence=proposal['sequence']) if resynchronize else state
    def exact(value):
        return json.dumps(value,sort_keys=True,ensure_ascii=False,separators=(',',':'))+'\n'
    writes={'state/authorized.json':exact(payload['approved_result'])}; deletes=[]
    if new_state is None: deletes=['state/protected.json']
    else: writes['state/protected.json']=exact(new_state)
    plan={'writes':writes,'deletes':deletes,'flow_marker':payload['flow_marker']}
    return {'plan_json':json.dumps(plan,sort_keys=True)}

def apply_plan(plan_json):
    import json
    from pathlib import Path
    plan=json.loads(plan_json)
    allowed={'state/protected.json','state/authorized.json'}
    if (set(plan['writes']) | set(plan['deletes'])) - allowed:
        raise ValueError('Unknown fixture path')
    for relative,body in plan['writes'].items():
        if not isinstance(body,str):
            raise ValueError('Expected exact text')
        target=Path('/work')/relative
        target.parent.mkdir(exist_ok=True)
        target.write_text(body)
    for relative in plan['deletes']:
        (Path('/work')/relative).unlink()
    return {'applied':True}

